"""Judgment, declaration and review; 2024 tie rule and current competence."""
import json,sys
from pathlib import Path
CPP='https://www.planalto.gov.br/ccivil_03/decreto-lei/del3689compilado.htm'
CF='https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm'
LAW='https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2024/lei/l14836.htm'
STJ='https://www.stj.jus.br/sites/portalp/Paginas/Comunicacao/Noticias/17102021-Condenacao-passada-a-limpo-a-revisao-criminal-e-a-jurisprudencia-do-STJ.aspx'
rows={}
def add(n,s,p,a,c,v,q,t,d,links=()):
 rows['art-'+str(n)]=dict(simples=s,pontos=p,atencao=[a],exemplo=c+' Variação: '+v,prova=q,termos=[dict(termo=t,significado=d)],remissoes=[CPP,*links])
add(609,'Competência recursal segue organização atual; decisão não unânime de segunda instância desfavorável pode admitir embargos na hipótese penal.', ['Dez dias da publicação do acórdão.', 'Divergência parcial: limitar matéria embargada.', 'Não estender automaticamente a qualquer decisão de qualquer tribunal.'], 'Unanimidade desfavorável não cria esses embargos; verificar cabimento e competência específicos.', 'Voto vencido favorável ao réu em matéria pertinente permite examinar embargos.', 'Divergência só de pena não autoriza reabrir toda imputação sem limite.', ['Prazo textual é dez dias? Sim.', 'Divergência parcial limita objeto? Sim.'], 'Embargos infringentes','Impugnação defensiva delimitada à divergência cabível.')
add(610,'Texto disciplina tramitação de RESE, exceto habeas corpus, e apelações de contravenção/detenção, integrado ao órgão atual.', ['Vista acusatória de cinco dias e relator por igual prazo.', 'Sustentação textual de dez minutos.', 'Integrar regimento e garantias de ciência/sustentação.'], 'Não aplicar de modo isolado a todo recurso, incluindo habeas corpus ou reclusão com modificações próprias.', 'Apelação pertinente é preparada para sessão com ciência regular.', 'Reclusão exige examinar art.613 e regras aplicáveis, não copiar só dez minutos.', ['HC segue indiscriminadamente esta regra? Não.', 'Há diferenciação de reclusão? Sim.'], 'Preparação de julgamento','Tramitação segundo espécie e regime aplicável.')
add(612,'Recurso de habeas corpus é julgado na primeira sessão após designação de relator no regime do artigo.', ['Prioridade ligada à tutela de liberdade.', 'Não excluir medidas urgentes cabíveis.'], 'Regra de sessão não autoriza ignorar pedido urgente até data distante.', 'Relator examina urgência e prepara julgamento prioritário.', 'Calendário não impede análise cautelar pertinente à liberdade.', ['Há prioridade de primeira sessão? Sim.', 'Urgência deve ser ignorada até sessão? Não.'], 'Prioridade do HC','Celeridade na tutela da liberdade.')
add(613,'Apelação de crime com reclusão integra art.610 com revisor, prazos dobrados e debate de quinze minutos, observadas normas atuais.', ['Revisor após relatório no modelo previsto.', 'Prazos do art.610 ampliados ao dobro.', 'Não dobrar prazo de interposição por esta regra interna.'], 'Não confundir preparo no tribunal com cinco dias para apelar.', 'Relatório segue a exame revisional conforme regime competente.', 'Apelante não ganha dez dias para interpor por crime prever reclusão.', ['Tempo textual de debate é quinze minutos? Sim.', 'Dobra automaticamente prazo de interposição? Não.'], 'Julgamento em reclusão','Modificações internas do processamento recursal.')
add(614,'Impossibilidade de cumprir prazos de610/613 precisa de motivos declarados nos autos.', ['Transparência da demora.', 'Não constitui autorização ilimitada de atraso.'], 'Registrar razão genérica não resolve todo excesso nem afasta controle de duração.', 'Órgão documenta causa real que impediu prazo.', 'Demora sem explicação não se justifica apenas por rotina administrativa.', ['Motivo deve constar dos autos? Sim.', 'Isso autoriza atraso sem limite? Não.'], 'Justificação da demora','Explicação documentada sujeita a controle.')
add(615,'Colegiado decide por maioria; Lei14836/2024 determina resultado mais favorável ao imputado em empate penal/processual penal.', ['Regra vale em todos os julgamentos colegiados da matéria.', 'Proclamar de imediato, inclusive falta de integrantes pelas causas enumeradas.', 'Não insistir em antigo voto de desempate desfavorável automático.', 'Acórdão: conferência na sessão seguinte ou prazo de duas conforme texto.'], 'Empate não autoriza prolongar julgamento só para obter voto condenatório; observar regra atual.', 'Dois votos por liberdade e dois contrários em hipótese penal levam ao resultado favorável pertinente.', 'Julgamento não penal não recebe essa regra automaticamente por analogia indiscriminada.', ['Empate penal atual favorece imputado? Sim.', 'Só se aplica ao HC? Não.'], 'Empate favorável','Solução legal atual dos votos empatados.',[LAW])
add(616,'Em apelação, tribunal pode realizar novo interrogatório, reinquirir ou determinar diligências, respeitando contraditório.', ['Não é obrigação de repetir toda prova.', 'Interrogatório conserva silêncio e defesa.'], 'Diligência não permite surpreender defesa com prova decisiva não comunicada.', 'Dúvida relevante demanda prova pertinente com participação das partes.', 'Réu não é forçado a confessar por novo interrogatório.', ['Pode haver diligência recursal? Sim.', 'Repete-se obrigatoriamente toda instrução? Não.'], 'Prova recursal','Esclarecimentos produzidos sob garantias na revisão da decisão.')
add(617,'Tribunal integra classificação, absolvição e condenação, mas não agrava pena quando só réu apelou.', ['Respeitar objeto e iniciativa recursal.', 'Não usar mudança jurídica para contornar proteção.', 'Examinar consequências e regime cabíveis.'], 'Apelação exclusiva da defesa não é oportunidade de aumentar pena por discordância do tribunal.', 'Defesa pede reduzir e tribunal não majora sanção na hipótese exclusiva.', 'Recurso acusatório pertinente exige análise de seus limites próprios.', ['Só defesa apelou: pode agravar pena? Não.', 'Recurso acusatório é situação idêntica? Não.'], 'Vedação de reformatio in pejus','Proteção contra agravamento no recurso exclusivo do réu.')
add(618,'Regimentos estabelecem regras complementares atuais de julgamento recursal, sem afastar lei e Constituição.', ['Nome histórico Tribunal de Apelação deve ser integrado.', 'Consultar órgão competente.', 'Norma complementar não cria supressão de defesa.'], 'Regimento não autoriza negar garantia nacional só por conveniência local.', 'Órgão aplica calendário e distribuição compatíveis com regime superior.', 'Norma interna contrária ao contraditório não é validada pelo artigo.', ['Regimento é complementar? Sim.', 'Pode afastar Constituição por este artigo? Não.'], 'Complementação regimental','Regras de organização subordinadas ao regime superior.')
add(619,'Embargos declaratórios do acórdão penal têm dois dias da publicação para ambiguidade, obscuridade, contradição ou omissão.', ['Distinguir prazo penal e CPC de cinco.', 'Identificar defeito efetivo.', 'Não confundir com embargos infringentes de dez.'], 'Simples derrota não cria omissão ou contradição interna.', 'Acórdão deixa ponto essencial sem exame: pedir integração pertinente.', 'Conclusão contrária à pretensão, clara e completa, não basta por si.', ['Prazo penal textual é dois dias? Sim.', 'São mesmos embargos infringentes? Não.'], 'Declaração do acórdão','Integração dos defeitos previstos na decisão colegiada.')
add(620,'Pedido declaratório indica pontos defeituosos; relator leva à sessão sem revisão ou indefere se faltam condições.', ['Expor trecho e defeito.', 'Primeira sessão no procedimento descrito.', 'Não presumir recurso admissível por nome da petição.'], 'Rótulo embargos não substitui indicação de omissão/contradição pertinente.', 'Parte identifica ponto omitido e efeito da integração requerida.', 'Pedido só repete argumento sem defeito indicado demanda exame de admissibilidade.', ['Indicar pontos é requisito? Sim.', 'Nome da petição garante acolhimento? Não.'], 'Fundamentação dos embargos','Demonstração do defeito a integrar.')
add(621,'Revisão de condenação finda cabe por contrariedade legal/probatória, prova falsa comprovada ou prova nova favorável na hipótese legal.', ['Não é segunda apelação livre.', 'Prova nova: inocência ou circunstância de diminuição especial.', 'Júri também admite revisão nos limites reconhecidos pelo STJ.'], 'Não rever toda prova apenas por preferência de outra interpretação; demonstrar hipótese revisional.', 'Documento comprovadamente falso sustentou condenação: examinar revisão.', 'Discordância genérica com pena sem fundamento legal revisional não basta.', ['Prova falsa comprovada é hipótese? Sim.', 'É nova apelação irrestrita? Não.'], 'Revisão criminal','Ação favorável contra condenação definitiva nas hipóteses legais.',[STJ])
add(622,'Revisão pode ser pedida a qualquer tempo, mesmo após extinção da pena; reiteração exige provas novas.', ['Não confundir com prazo de apelação.', 'Novo pedido precisa respeitar ressalva.'], 'Trocar redação da petição não equivale a prova nova.', 'Pessoa que já cumpriu pena pode requerer revisão cabível.', 'Pedido idêntico sem novas provas não se renova livremente.', ['Pena cumprida impede sempre revisão? Não.', 'Reiteração sem prova nova é livre? Não.'], 'Tempo revisional','Ausência de prazo extintivo da ação favorável.')
add(623,'Revisão pode ser pedida pelo réu ou procurador habilitado; se réu morreu, pelos familiares enumerados.', ['Cônjuge, ascendente, descendente ou irmão.', 'STJ reconhece faculdade de pedido pelo próprio réu.', 'Distinguir legitimação e prova do cabimento.'], 'Ser familiar não dispensa hipótese revisional nem alcança automaticamente toda pessoa próxima.', 'Após morte, filha pede revisão com documentação pertinente.', 'Amigo sem legitimidade legal não entra automaticamente como descendente.', ['Réu pode pedir por si na regra? Sim.', 'Irmão é enumerado após morte? Sim.'], 'Legitimidade revisional','Titulares autorizados ao pedido favorável.',[STJ])
add(624,'Competência revisional exige integração à Constituição e tribunais atuais; TFR e Alçada históricos não definem destinatário contemporâneo.', ['STF: condenações por ele proferidas no regime cabível.', 'STJ/TRFs/TJs: identificar competência constitucional e decisão própria.', 'Composição interna segue organização/regimento atual.'], 'Não encaminhar a órgão extinto nem atribuir revisão ao STJ só porque houve recurso nele sem examinar mérito e competência.', 'Condenação estadual é examinada pelo órgão revisional competente segundo caso.', 'Recurso excepcional inadmitido não transfere automaticamente toda revisão ao superior.', ['TFR antigo é órgão atual para protocolar? Não.', 'Competência precisa ser identificada pelo caso? Sim.'], 'Competência da revisão','Órgão apto no sistema constitucional atual.',[CF])
add(625,'Pedido revisional deve mostrar trânsito e fatos, com relator não participante de decisão anterior e procedimento de exame.', ['Certidão e peças necessárias; apensamento se não prejudicar execução.', 'Pedido insuficiente pode ser indeferido; recurso interno na hipótese prevista.', 'Não indeferido: MP, relator e revisor por dez dias cada no modelo.', 'Integrar remissão antiga de organização ao regimento atual.'], 'Revisão não dispensa prova da condenação definitiva nem permite preencher fatos por suposição.', 'Parte junta certidão e prova nova pertinente.', 'Relator que antes decidiu processo exige atenção à vedação prevista.', ['Precisa comprovar trânsito? Sim.', 'Relator deve ter pronunciado decisão antes? Não, regra exige que não.'], 'Instrução revisional','Documentação e exame do pedido de revisão.')
add(626,'Revisão procedente pode reclassificar, absolver, modificar pena ou anular processo, nunca agravar pena revista.', ['Consequência depende do fundamento.', 'Não se limita apenas a absolvição.', 'Revisão é favorável ao condenado.'], 'Não aumentar pena para corrigir erro contra acusação nesta via.', 'Erro legal de pena é corrigido favoravelmente na hipótese cabível.', 'Anulação pode ser resultado adequado, não necessariamente absolvição em todo caso.', ['Pode agravar pena revista? Não.', 'Anulação é resultado possível? Sim.'], 'Efeito da revisão','Providência favorável adequada ao vício reconhecido.')
add(627,'Absolvição revisional restabelece direitos perdidos pela condenação; medida de segurança só se juridicamente cabível.', ['Examinar efeitos vinculados à condenação desconstituída.', 'Diagnóstico ou ausência de prova não impõem medida automaticamente.'], 'Não trocar absolvição por internação punitiva sem pressupostos atuais.', 'Pessoa absolvida recupera direitos afetados pela condenação nos termos pertinentes.', 'Prova de não participação não autoriza medida de segurança por simples condição médica.', ['Medida cabe automaticamente em toda revisão procedente? Não.', 'Absolvição tem efeito restaurador de direitos? Sim.'], 'Restabelecimento de direitos','Consequências da condenação desconstituída.')
add(628,'Regimento complementa processamento da revisão no órgão competente, subordinado a lei e Constituição.', ['Integrar nome antigo de Tribunal de Apelação.', 'Não modificar pressupostos materiais por regra administrativa.'], 'Norma interna não transforma revisão em recurso acusatório para agravar pena.', 'Órgão organiza distribuição e sessão conforme regimento válido.', 'Prazo interno não elimina garantia de defesa ou competência constitucional.', ['Regimento é complemento? Sim.', 'Pode autorizar agravamento vedado? Não.'], 'Revisão e regimento','Organização da ação sob normas superiores.')
add(629,'Certidão do acórdão que cassa condenação é juntada imediatamente para inteiro cumprimento da decisão.', ['Concretizar resultado judicial.', 'Não aguardar conveniência administrativa para ajustar efeitos.'], 'Reconhecer revisão sem executar providências não satisfaz decisão.', 'Juízo recebe certidão e implementa alteração de pena ou liberdade pertinente.', 'Erro no cadastro deve ser corrigido segundo título, não mantido por desatenção.', ['Juntada é imediata na regra? Sim.', 'Cumprimento pode ser ignorado após decisão? Não.'], 'Efetivação revisional','Aplicação prática do acórdão favorável.')
add(630,'A pedido, tribunal pode reconhecer indenização justa; liquidação é cível e leitura deve integrar garantia constitucional de erro judiciário.', ['Examinar erro, danos e nexo.', 'Não é pagamento automático em todo resultado revisional.', 'Responsável e remissões de justiça territorial exigem sistema atual.', 'Exclusões textuais devem ser analisadas constitucionalmente, sem negar direito universal por rótulo de ação privada.'], 'Não prometer indenização automática nem aplicar exclusão antiga sem examinar CF5º,LXXV e regime de responsabilidade.', 'Erro de condenação com danos demonstrados fundamenta pedido e análise.', 'Revisão sem demonstração de dano ou pressuposto não fixa valor indenizatório por simples nome.', ['Revisão garante pagamento automático? Não.', 'Liquidação da indenização ocorre no cível? Sim.'], 'Indenização por erro','Reparação sujeita ao regime constitucional e pressupostos.',[CF])
add(631,'Se pessoa revisanda morre durante ação, presidente nomeia curador para defesa.', ['Proteção da defesa no processo em curso.', 'Distinguir familiares que iniciam pedido após morte, art.623.', 'Não confundir com curador antigo por menor de21.'], 'Morte não encerra necessariamente exame revisional nem restaura regra etária antiga.', 'Óbito durante revisão leva à nomeação para continuidade defensiva.', 'Falecimento anterior ao ajuizamento exige examinar legitimados do art.623.', ['Morte durante revisão tem regra de curador? Sim.', 'É curadoria apenas por ter vinte anos? Não.'], 'Curadoria revisional','Defesa do interesse revisional após morte no curso da ação.')
assert len(rows)==22
Path(sys.argv[1]).write_text(json.dumps({'course_slug':'codigo-processo-penal','units':rows},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(len(rows),'judgment revision units reviewed')
